# Two points
var point_one: Vector3 = Vector3(0.0, 1.0, 0.0)
var point_two: Vector3 = Vector3(1.0, 1.0, 0.0)

# The relation between them
var distance: float = point_one.distance_to(point_two)
var direction: Vector3 = (point_two - point_one).normalized()

# distance = 1.0
# direction = (1, 0, 0) — pointing right
# The line has no independent existence.
# It IS the relation.

extends Node3D

@export var line_thickness: float = 0.005
@export var line_color: Color = Color(1.0, 1.0, 1.0)

@onready var point_one = $GrabSphere
@onready var point_two = $GrabSphere2

var current_line: MeshInstance3D
var length_label: Label3D

func _ready():
	create_length_label()
	update_connections()

func create_connection_line(start_pos: Vector3, end_pos: Vector3) -> MeshInstance3D:
	var line = MeshInstance3D.new()
	var cylinder = CylinderMesh.new()
	cylinder.height = start_pos.distance_to(end_pos)
	cylinder.top_radius = line_thickness
	cylinder.bottom_radius = line_thickness
	line.mesh = cylinder

	# Position at midpoint
	line.position = (start_pos + end_pos) / 2.0
	add_child(line)
	return line

func _process(_delta):
	if point_one and point_two:
		update_line_transform(point_one.position, point_two.position)
		update_length_label(point_one.position, point_two.position)

		if enable_resistance:
			_process_resistance(
				point_one.position.distance_to(point_two.position)
			)

func _process_resistance(distance: float):
	# How close to the nearest integer?
	var remainder = fmod(distance, 1.0)
	var dist_to_int = min(remainder, 1.0 - remainder)

	if dist_to_int < resistance_threshold:
		var t = 1.0 - (dist_to_int / resistance_threshold)
		var intensity = pow(t, 2.0)  # Non-linear: gentle at edges, fierce at center

		# 1. Visual: the line jitters
		current_line.position += Vector3(
			randf_range(-1, 1),
			randf_range(-1, 1),
			randf_range(-1, 1)
		) * max_jitter * intensity

		# 2. Audio: white noise crackle
		_glitch_player.volume_db = lerp(-40.0, glitch_sound_volume_db, intensity)
		_glitch_player.pitch_scale = 1.0 + (randf() - 0.5) * intensity

		# 3. Haptic: controller vibrates
		controller.trigger_haptic_pulse("haptic", 100.0 + intensity * 200.0, intensity * 0.8, 0.05, 0)

		# 4. Label flashes red
		if randf() < intensity * 0.2:
			length_label.modulate = Color.RED

func _generate_glitch_stream() -> AudioStreamWAV:
	var stream := AudioStreamWAV.new()
	stream.format = AudioStreamWAV.FORMAT_16_BITS
	stream.mix_rate = 22050
	var duration := 0.5  # Short loop
	var length := int(stream.mix_rate * duration)
	var data := PackedByteArray()
	data.resize(length * 2)

	for i in length:
		# White noise with occasional spikes
		var sample: float = randf_range(-1.0, 1.0) * 0.8
		if randf() > 0.95:
			sample = sign(sample) * 1.0  # Crackle

		var int_sample: int = int(sample * 32767.0)
		data[2 * i] = int_sample & 0xFF
		data[2 * i + 1] = (int_sample >> 8) & 0xFF

	stream.data = data
	stream.loop_mode = AudioStreamWAV.LOOP_FORWARD
	return stream
